    // 6. Close observer node (remove from graph / cleanup relationships)
    graph.removeNode(observer);

    // 7. Notify target again
    target->valueChanged(true);

    // 8. Verify observer was not notified after closure
    if (observer->getCallCount() != 2) {
        // It should only have been called directly twice:
        //   - once from target notification
        //   - once when we reset its state explicitly
        return false;
    }

    // 9. Return success status
    return true;
}

}  // namespace test_reaction

