#pragma once

#include <reaction/core/observer_node.h>
#include <reaction/graph/observer_graph.h>
#include <memory>
#include <string>

namespace test_reaction {

// ============================================
// Data model definitions
// ============================================

class TestTransactionalObserver : public reaction::ObserverNode {
public:
    TestTransactionalObserver(const std::string& name) : m_name(name), m_changed(false) {}

    void valueChanged(bool changed = true) override {
        m_changed = changed;
        m_callCount++;
        // Call base class to propagate notification to observers
        ObserverNode::valueChanged(changed);
    }

    bool wasChanged() const { return m_changed; }
    int getCallCount() const { return m_callCount; }
    const std::string& getName() const { return m_name; }

    void reset() {
        m_changed = false;
        m_callCount = 0;
    }

private:
    std::string m_name;
    bool m_changed;
    int m_callCount = 0;
};

// ============================================
// Function implementations
// ============================================

/**
 * Function: Test transactional observer updates
 *
 * @param nodeName Name for the node to update
 * @return bool Whether transactional update succeeded (no cycle created)
 */
bool test_transactional_update(const std::string& nodeName) {
    using reaction::ObserverGraph;
    using NodePtr = ObserverGraph::NodePtr;

    // 1. Create observer nodes
    auto source      = std::make_shared<TestTransactionalObserver>("source");
    auto middle      = std::make_shared<TestTransactionalObserver>("middle");
    auto target      = std::make_shared<TestTransactionalObserver>(nodeName);
    auto extra       = std::make_shared<TestTransactionalObserver>("extra");
    auto cycleSource = std::make_shared<TestTransactionalObserver>("cycleSource");

    // 2. Get observer graph instance
    auto& graph = ObserverGraph::instance();

    // 3. Set up initial relationship: source -> middle -> target
    graph.updateObservers(source, middle);
    graph.updateObservers(middle, target);

    // 4. Notify target and verify relationship works
    target->reset();
    middle->reset();
    source->reset();

    source->valueChanged(true);

    if (!target->wasChanged() || target->getCallCount() == 0)
        return false;

    // 5. Reset observer for next test
    target->reset();
    middle->reset();
    source->reset();

    // 6. Attempt transactional update that would create cycle:
    //    Make target observe source and cycleSource, and then later
    //    (implicitly via graph) source/middle still lead to target,
    //    so we try to create a back-edge target -> source that
    //    should create a cycle.
    bool cycleDetected = false;
    try {
        graph.updateObserversTransactional(target, source, extra, cycleSource);
    } catch (const std::exception&) {
        cycleDetected = true;
    }

    // 7. Catch cycle exception if thrown
    // (cycleDetected already reflects that)

    // 8. Notify target again via original path: source -> middle -> target
    source->valueChanged(true);

    // 9. Verify original relationship is preserved:
    //    target should still be notified exactly once more through
    //    the existing source -> middle -> target chain.
    if (!target->wasChanged() || target->getCallCount() == 0)
        return false;

    // 10. Return success status:
    //     transactional update must not have succeeded if it created cycle,
    //     so we succeed when cycle was detected and original graph intact.
    return cycleDetected;
}

}  // namespace test_reaction

