                                                      double secondUpdate,
                                                      double diffThreshold,
                                                      double levelThreshold) {
    using namespace reaction;

    // 1. Create reactive variable
    auto sensor = var(initialValue).setName("sensor");

    // 2. Create variables to track recomputation count and last processed value
    int recomputeCount = 0;
    double lastProcessed = initialValue;

    // 3. Create filter-triggered calculation
    //    Recomputes only if |sensor - lastProcessed| >= diffThreshold
    auto status = calc([&]() -> std::string {
        double current = sensor.get();
        if (std::abs(current - lastProcessed) < diffThreshold) {
            // No effective change; keep old recompute state
            return lastProcessed >= levelThreshold ? std::string("HIGH")
                                                   : std::string("NORMAL");
        }

        // Effective change detected
        lastProcessed = current;
        ++recomputeCount;

        return current >= levelThreshold ? std::string("HIGH")
                                         : std::string("NORMAL");
    }).setName("status");

    // Initial evaluation to establish baseline
    auto initialStatus = status.get();
    (void)initialStatus; // silence unused warning

    // 4. Apply filter
    // (Filtering logic is embedded in calc above via lastProcessed / diffThreshold)

    // 5. Update sensor with first value
    sensor.value(firstUpdate);

    // 6. Record recompute count after first update
    // Accessing status will trigger calc if filter condition passes
    auto statusAfterFirst = status.get();
    (void)statusAfterFirst;
    int countAfterFirst = recomputeCount;

    // 7. Update sensor with second value
    sensor.value(secondUpdate);

    // 8. Record recompute count after second update
    auto statusAfterSecond = status.get();
    (void)statusAfterSecond;
    int countAfterSecond = recomputeCount;

    // 9. Get final status
    std::string finalStatus = status.get();

    // 10. Return final status and counts
    return std::make_tuple(finalStatus, countAfterFirst, countAfterSecond);
}

}  // namespace test_reaction
