#pragma once

#include <reaction/reaction.h>

namespace test_reaction {

// ============================================
// Helper types
// ============================================

class RecordingNode : public reaction::ObserverNode {
public:
    void valueChanged(bool changed = true) override {
        if (changed) {
            ++m_notifications;
        }
    }

    int notificationCount() const {
        return m_notifications;
    }

private:
    int m_notifications = 0;
};

struct RollbackObservation {
    int notificationsAfterSecondBinding;
    int notificationsAfterRollback;
};

// ============================================
// Function implementation
// ============================================

inline RollbackObservation test_observer_state_rollback() {
    using namespace reaction;

    // 1. Create RecordingNode instances
    RecordingNode node1;
    RecordingNode node2;

    // 2. Get observer graph instance
    auto& graph = ObserverGraph::instance();

    // 3. Register nodes
    // The ids are arbitrary but must be consistent for subsequent calls.
    const std::string id1 = "sensor_1";
    const std::string id2 = "sensor_2";

    graph.registerObserver(id1, &node1);
    graph.registerObserver(id2, &node2);

    // 4. Set up initial dependency: sensor_1 -> node1
    // We model "sensor" as a dependency key; here we use "sensor_1" and "sensor_2"
    // as both ids and keys for simplicity.
    graph.addDependency(id1, id1);  // node1 depends on sensor_1

    // 5. Save node state for rollback
    auto stateToken = graph.saveObserverState();

    // 6. Replace dependencies transactionally:
    //    Remove old dependency and add new one within a batch / transaction.
    g_batch_execute([&] {
        graph.removeDependency(id1, id1);  // remove sensor_1 -> node1
        graph.addDependency(id2, id1);     // sensor_2 -> node1
    });

    // 7. Trigger notification on second sensor
    graph.notifyObservers(id2);

    // 8. Record notification count after second binding
    RollbackObservation result{};
    result.notificationsAfterSecondBinding = node1.notificationCount();

    // 9. Execute rollback
    graph.restoreObserverState(stateToken);

    // 10. Trigger notification on first sensor again
    graph.notifyObservers(id1);

    // 11. Record notification count after rollback
    result.notificationsAfterRollback = node1.notificationCount();

    // 12. Return notification counts
    return result;
}

}  // namespace test_reaction
