inline ThreadSafetyStatus test_thread_manager_multithread() {
    using reaction::ThreadManager;

    // 1. Get thread manager instance
    auto &manager = ThreadManager::getInstance();

    // 2. Reset thread manager state
    manager.resetForTesting();

    // 3. Register current (main) thread
    manager.registerCurrentThread();

    // 4. Get thread count and safety status before
    ThreadSafetyStatus status{};
    status.threadCountBefore = manager.getThreadCount();
    status.safetyBefore = manager.isThreadSafe();

    // 5. Create and start worker thread
    std::thread worker([&manager]() {
        // Register worker thread with the manager
        manager.registerCurrentThread();
        // Optionally query status to ensure internal state is exercised
        (void)manager.isThreadSafe();
    });

    // 6. Wait for worker thread
    if (worker.joinable()) {
