#pragma once

#include <reaction/reaction.h>

namespace test_reaction {

class CacheProbeNode : public reaction::ObserverNode {
public:
    void valueChanged(bool changed = true) override {
        (void)changed;
    }
};

struct CacheStatsSnapshot {
    size_t graphEntriesBeforeCleanup;
    size_t graphEntriesAfterCleanup;
    double graphHitRatioAfterCleanup;
};

CacheStatsSnapshot test_observer_cache_stats() {
    using namespace reaction;

    // 1. Create CacheProbeNode instances
    auto n1 = std::make_shared<CacheProbeNode>();
    auto n2 = std::make_shared<CacheProbeNode>();
    auto n3 = std::make_shared<CacheProbeNode>();

    // 2. Get observer graph instance
    auto &graph = ObserverGraph::getInstance();

    // 3. Register nodes
    graph.registerNode("n1", n1);
    graph.registerNode("n2", n2);
    graph.registerNode("n3", n3);

    // 4. Set up direct observer relationship: n2 observes n1
    graph.addObserver(n1, n2);

    // 5. Set up transitive observer relationship: n3 observes n2 (thus transitively n1)
    graph.addObserver(n2, n3);

    // 6. Create NodeSet to store collected observers
    NodeSet observers;

    // 7. Populate cache data by querying observers, which should fill the cache
    graph.getObservers(n1, observers);
    observers.clear();
    graph.getObservers(n2, observers);

    // 8. Get cache statistics before cleanup
    auto statsBefore = graph.getCacheStats();
    size_t entriesBefore = statsBefore.entries;

    // 9. Trigger cache cleanup
    graph.triggerCacheCleanup();

    // 10. Get cache statistics after cleanup
    auto statsAfter = graph.getCacheStats();
    size_t entriesAfter = statsAfter.entries;
    double hitRatioAfter = statsAfter.hitRatio;

    // 11. Close all nodes (unregister from graph)
    graph.unregisterNode("n1");
    graph.unregisterNode("n2");
    graph.unregisterNode("n3");

    // 12. Return cache stats snapshot
    CacheStatsSnapshot snapshot{
        entriesBefore,
        entriesAfter,
        hitRatioAfter,
    };
    return snapshot;
}

}  // namespace test_reaction

