            payload.data[i] = largeSeed + static_cast<int>(i);
        }
        return payload;
    };

    // 2. Create small SBOResource
    reaction::SBOResource<SmallPayload> small_resource(SmallPayload{initialSmall});

    // 3. Create large SBOResource
    reaction::SBOResource<LargePayload> large_resource(make_large_payload());

    // 4. Update small resource value
    bool updateReportedChange = small_resource.update(
        [updatedSmall](SmallPayload& payload) {
            bool changed = (payload.value != updatedSmall);
            payload.value = updatedSmall;
            return changed;
        });

    // 5. Get storage information for small resource
    auto small_info = small_resource.getStorageInfo();

    // 6. Get storage information for large resource
    auto large_info = large_resource.getStorageInfo();

    // 7. Return SBO storage status
    return SboStorageStatus{
        .updateReportedChange = updateReportedChange,
        .smallUsingSBO = small_info.using_sbo,
        .smallStackUsage = small_info.stack_usage,
        .largeInitialized = large_info.initialized,
        .largeUsingSBO = large_info.using_sbo,
    };
}

}  // namespace test_reaction

