```cpp
#pragma once

#include <reaction/reaction.h>

namespace test_reaction {

struct ResetBehaviorSnapshot {
    int beforeResetValue;
    int afterResetValue;
    bool safetyEnabledDuringReset;
};

inline ResetBehaviorSnapshot test_react_reset_behavior(int initialValue, int multiplier) {
    using namespace reaction;

    // 1. Get thread manager instance
    auto& manager = ThreadManager::instance();

    // 2. Reset thread manager state
    manager.reset();

    // 3. Create a reactive variable
    auto source = var(initialValue);

    // 4. Create a calculation
    auto calcExpr = calc([&]() {
        return source.get() * multiplier;
    });

    // 5. Get value before reset
    int beforeResetValue = calcExpr.get();

    // 6. Enable thread safety
    manager.enableThreadSafety(true);

    // 7. Check if thread safety is enabled
    bool safetyEnabledDuringReset = manager.isThreadSafetyEnabled();

    // 8. Reset calculation logic:
    //    For the purpose of this test, emulate "reset" by resetting the manager
    //    and recreating the calculation (so it rebinds to the current graph).
    manager.reset();
    // Recreate the calculation after reset
    auto calcExprAfterReset = calc([&]() {
        return source.get() * multiplier;
    });

    // 9. Update source variable
    source.value(initialValue + 1);

    // 10. Get value after reset
    int afterResetValue = calcExprAfterReset.get();

    // 11. Return reset behavior snapshot
    return ResetBehaviorSnapshot{
        beforeResetValue,
        afterResetValue,
        safetyEnabledDuringReset,
    };
}

}  // namespace test_reaction
