```cpp
#pragma once

#include <reaction/memory/memory_config.h>
#include <reaction/memory/stack_monitor.h>

namespace test_reaction {

struct StackAllocationSnapshot {
    bool smallAllowedWithoutMonitoring;
    bool largeAllowedWithoutMonitoring;
    bool runtimeAllowedWithoutMonitoring;
    bool largeAllowedWithMonitoring;
    bool guardSucceeded;
    bool allocationBlockedAtLimit;
    bool runtimeAllowedAfterRelease;
};

/**
 * Function: Demonstrate StackMonitor::canAllocate behaviour across modes.
 *
 * @param largeSize Value used for runtime canAllocate after release
 * @return StackAllocationSnapshot Snapshot of allocation checks before/after guard
 */
inline StackAllocationSnapshot test_stack_monitor_capacity(std::size_t largeSize) {
    using reaction::memory::StackMonitor;
    using reaction::memory::SBOConfig;

    StackAllocationSnapshot snapshot{};

    // 1) Disable monitoring
    StackMonitor::disableMonitoring();

    // 2) Initialize stack monitor state (ensure usage reset)
    StackMonitor::reset();

    // 3) Check allocation without monitoring
    constexpr std::size_t smallSize = SBOConfig::CONDITIONAL_SBO_SIZE;
    snapshot.smallAllowedWithoutMonitoring = StackMonitor::canAllocate<smallSize>();

    const std::size_t tooLargeNoMon = SBOConfig::CONDITIONAL_SBO_SIZE + 1;
    snapshot.largeAllowedWithoutMonitoring = StackMonitor::canAllocate(tooLargeNoMon);

    // runtime check without monitoring (should be same rule as template)
    snapshot.runtimeAllowedWithoutMonitoring = StackMonitor::canAllocate(largeSize);

    // 4) Enable monitoring
    StackMonitor::enableMonitoring();

    // 5) Initialize stack monitor again (reset usage)
    StackMonitor::reset();

    // 6) Check large allocation with monitoring (just below/at limit allowed)
    const std::size_t nearLimit =
        (SBOConfig::MAX_SBO_STACK_USAGE > 0)
            ? SBOConfig::MAX_SBO_STACK_USAGE
            : SBOConfig::CONDITIONAL_SBO_SIZE;
    snapshot.largeAllowedWithMonitoring = StackMonitor::canAllocate(nearLimit);

    // 7) Create StackGuard in scope block
    {
        // choose a guard size that fits under MAX_SBO_STACK_USAGE
        constexpr std::size_t guardSize =
            (SBOConfig::MAX_SBO_STACK_USAGE > 0
                 ? (SBOConfig::MAX_SBO_STACK_USAGE / 2)
                 : SBOConfig::CONDITIONAL_SBO_SIZE);

        StackMonitor::StackGuard<guardSize> guard;

        // 8) Check if guard succeeded
        snapshot.guardSucceeded = guard.success();

        // 9) Check if allocation blocked at limit
        const std::size_t remaining =
            (SBOConfig::MAX_SBO_STACK_USAGE > guardSize)
                ? (SBOConfig::MAX_SBO_STACK_USAGE - guardSize)
                : 0;

        const bool canUseRemaining = StackMonitor::canAllocate(remaining);
        const bool canExceed =
            StackMonitor::canAllocate(SBOConfig::MAX_SBO_STACK_USAGE + 1);

        snapshot.allocationBlockedAtLimit = canUseRemaining && !canExceed;

        // guard goes out of scope at end of this block
    }

    // 10) Exit guard scope (done by block above)

    // 11) Check runtime allocation after release
    snapshot.runtimeAllowedAfterRelease = StackMonitor::canAllocate(largeSize);

    // 12) Return stack allocation snapshot
    return snapshot;
}

}  // namespace test_reaction
