 * `expr` factory to produce reactive expressions.
 *
 * @param a First input value participating in the sum expression
 * @param b Second input value participating in the sum expression
 * @return UnaryExpressionSnapshot Snapshot of expression outputs before/after updates
 */
inline UnaryExpressionSnapshot test_unary_expression_builders(int a, int b) {
    using namespace reaction;

    // 1. Create reactive variables for arithmetic part
    auto varA = var(a).setName("unary_a");
    auto varB = var(b).setName("unary_b");

    // 2. Build negated sum expression:
    //    - first use expression builders to create a reactive sum: a + b
    //    - then apply high-level unary negation: -(a + b)
    auto sum_expr = expr(make_binary_op<AddOp>(varA, varB)).setName("sum_expr");
    auto negated_sum_expr =
        expr(make_unary_op<NegateOp>(sum_expr)).setName("negated_sum_expr");

    // 3. Create reactive boolean variable
    auto bool_var = var(true).setName("unary_bool");

    // 4. Build logical NOT expression using high-level operator
    auto not_expr = expr(!bool_var).setName("not_expr");

    // 5. Create reactive integer variable for bitwise NOT
    auto int_var = var(0b1010).setName("unary_int");  // 10 in binary

    // 6. Build bitwise NOT expression using high-level operator
    auto bitnot_expr = expr(~int_var).setName("bitnot_expr");

    // 7. Get initial negated sum value
    int initialNegatedSum = negated_sum_expr.get();

    // 8. Update variables to trigger recomputation
    //    For demonstration: change a and b, flip bool, and change int_var
    varA.value(a + 1);
    varB.value(b + 2);
    bool_var.value(false);
    int_var.value(0b1100);  // 12 in binary

    // 9. Get updated values
    int updatedNegatedSum = negated_sum_expr.get();
    bool logicalNotAfterFlip = not_expr.get();
    int bitwiseNotValue = bitnot_expr.get();

    // 10. Return unary expression snapshot
    return UnaryExpressionSnapshot{
        initialNegatedSum,
        updatedNegatedSum,
        logicalNotAfterFlip,
        bitwiseNotValue
    };
}

}  // namespace test_reaction
