#pragma once

#include <reaction/cache/graph_cache.h>
#include <reaction/core/observer_node.h>
#include <memory>

namespace test_reaction {

struct NodeMetricsCacheSnapshot {
    std::size_t entriesBefore;
    std::size_t entriesAfterCache;
    std::size_t entriesAfterInvalidate;
    std::size_t hitCount;
    std::size_t missCount;
    double hitRatio;
    bool metricsCachedExists;
    bool metricsClearedAfterInvalidate;
};

inline NodeMetricsCacheSnapshot test_node_metrics_cache() {
    using namespace reaction;

    NodeMetricsCacheSnapshot snapshot{};

    // 1. Create NodeMetricsCache instance
    NodeMetricsCache cache;

    // 2. Create ObserverNode instance
    auto node = std::make_shared<ObserverNode>();

    // 3. Get cache statistics before caching
    auto statsBefore = cache.getStats();
    snapshot.entriesBefore = statsBefore.entryCount;

    // 4. Query metrics before caching (expect miss)
    const auto *metricsBefore = cache.getCachedNodeMetrics(node);
    (void)metricsBefore; // metricsBefore is expected to be nullptr
    auto statsAfterMiss = cache.getStats(); // miss counter should increase
    snapshot.missCount = statsAfterMiss.missCount;

    // 5. Cache node metrics
    bool exists = true;
    std::size_t observerCount = 3;
    std::size_t dependentCount = 2;
    uint8_t maxDepth = 5;
    cache.cacheNodeMetrics(node, exists, observerCount, dependentCount, maxDepth);

    // 6. Query metrics after caching (expect hit)
    const auto *metricsAfter = cache.getCachedNodeMetrics(node);
    snapshot.metricsCachedExists = (metricsAfter != nullptr) && metricsAfter->exists;

    // 7. Get cache statistics after caching
    auto statsAfterHit = cache.getStats();
    snapshot.entriesAfterCache = statsAfterHit.entryCount;
    snapshot.hitCount = statsAfterHit.hitCount;
    snapshot.hitRatio = statsAfterHit.hitRatio;

    // 8. Invalidate all entries
    cache.invalidateAll();

    // 9. Query metrics after invalidation (expect miss)
    const auto *metricsAfterInvalidate = cache.getCachedNodeMetrics(node);
    snapshot.metricsClearedAfterInvalidate = (metricsAfterInvalidate == nullptr);

    // 10. Get cache statistics after invalidation
    auto statsAfterInvalidate = cache.getStats();
    snapshot.entriesAfterInvalidate = statsAfterInvalidate.entryCount;
    // We don't override hit/miss/hitRatio again here; we keep what we gathered earlier

    // 11. Return node metrics cache snapshot
    return snapshot;
}

}  // namespace test_reaction

