    auto negated_raw = make_unary_expr(
        sum_raw,
        std::negate<>{} // equivalent to unary -
    );

    auto negated = expr(negated_raw).setName("negated");

    // 4. Build chained expression: chained = (-(A + B)) * C
    //    Nested make_* calls: first negated_raw, then multiply with C.
    auto chained_raw = make_binary_expr(
        negated_raw,
        C,
        std::multiplies<>{} // equivalent to operator*
    );

    auto chained = expr(chained_raw).setName("chained");

    // 5. Get initial expression values
    RawExpressionSnapshot snapshot{};
    snapshot.initialSum           = sum.get();
    snapshot.initialNegatedSum    = negated.get();
    snapshot.initialChainedValue  = chained.get();

    // 6. Update variables to trigger recomputation
    //    For demonstration, change A and C by simple deterministic offsets.
    A.value(a + 1);
    C.value(c + 2);

    // 7. Get updated expression values
    snapshot.updatedSum           = sum.get();
    snapshot.updatedNegatedSum    = negated.get();
    snapshot.updatedChainedValue  = chained.get();

    // 8. Return raw expression snapshot
    return snapshot;
}

